(() => {
  if (window.__pcBiliSpeedInit) return;
  window.__pcBiliSpeedInit = true;

  let toastTimer = null;
  function showHud(text) {
    let el = document.getElementById('pc-speed-hud');
    if (!el) {
      el = document.createElement('div');
      el.id = 'pc-speed-hud';
      el.style.cssText = 'position:fixed;top:18px;right:18px;z-index:2147483647;padding:6px 12px;border-radius:8px;background:rgba(28,25,23,0.88);color:#FAF8F5;font:600 13px/1.3 ui-monospace,monospace;pointer-events:none;transition:opacity .18s ease;box-shadow:0 8px 20px rgba(0,0,0,.22)';
      document.body.appendChild(el);
    }
    el.textContent = text;
    el.style.opacity = '1';
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(() => {
      el.style.opacity = '0';
    }, 1100);
  }

  window.addEventListener('keydown', (e) => {
    const t = e.target;
    if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    if (e.key !== '[' && e.key !== ']' && e.key !== '\\') return;
    const video = document.querySelector('video');
    if (!video) return;
    const next = e.key === '\\'
      ? 1
      : Math.min(4, Math.max(0.25, Math.round((video.playbackRate + (e.key === ']' ? 0.25 : -0.25)) * 100) / 100));
    video.playbackRate = next;
    showHud(next.toFixed(2).replace(/\.00$/, '') + 'x');
  });
})();

