(() => {
  function unwrapLinks(root) {
    const anchors = (root || document).querySelectorAll('a[href*="link.zhihu.com"]');
    for (const a of anchors) {
      try {
        const u = new URL(a.href);
        const target = u.searchParams.get('target');
        if (target && /^https?:\/\//i.test(target)) {
          a.href = target;
          a.removeAttribute('data-za-detail-view-id');
        }
      } catch {
        /* skip malformed URL */
      }
    }
  }
  unwrapLinks(document);
  const obs = new MutationObserver(() => unwrapLinks(document));
  if (document.body) obs.observe(document.body, { childList: true, subtree: true });
})();

