table {
  font-variant-numeric: tabular-nums;
}
table tbody tr:hover {
  background: rgba(201, 85, 51, 0.06) !important;
}
table thead th {
  position: sticky;
  top: 0;
}

(() => {
  const tables = document.querySelectorAll('table');
  for (const tbl of tables) {
    if (tbl.dataset.pcCsvReady || tbl.rows.length < 3) continue;
    tbl.dataset.pcCsvReady = '1';
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.textContent = 'Export CSV';
    btn.style.cssText = 'display:inline-flex;align-items:center;margin:0 0 6px;padding:3px 9px;border-radius:6px;border:1px solid #C95533;background:#FAF8F5;color:#9A3412;font:600 11.5px/1.3 system-ui,sans-serif;cursor:pointer';
    btn.addEventListener('click', () => {
      const rows = Array.from(tbl.querySelectorAll('tr')).map((tr) =>
        Array.from(tr.children).map((td) => {
          const txt = (td.textContent || '').replace(/\s+/g, ' ').trim().replace(/"/g, '""');
          return `"${txt}"`;
        }).join(','),
      );
      const csv = '\uFEFF' + rows.join('\n');
      const link = document.createElement('a');
      link.href = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csv);
      link.download = (document.title.slice(0, 32) || 'table').replace(/[^\w-]+/g, '-') + '.csv';
      document.body.appendChild(link);
      link.click();
      link.remove();
    });
    tbl.parentNode.insertBefore(btn, tbl);
  }
})();

